for slug,titles in [('privacy',privacyTitles),('terms',termsTitles)]:
 source=(r/slug/'index.html').read_text()
 english=re.findall(r'<section id="section-\d+"><h2>\d+\. (.*?)</h2>',source)
 for en,ar in zip(english,titles):T[en]=ar

def tr(text):
 stripped=text.strip()
 if stripped in T:return text.replace(stripped,T[stripped])
 m=re.match(r'^(\d+)\. (.*)$',stripped)
 if m and m[2] in T:return text.replace(stripped,m[1]+'. '+T[m[2]])
 return text

def switcher(href,arabic):
 return f'<a class="language-switch" href="{href}" lang="'+('en' if arabic else 'ar')+'" dir="'+('ltr' if arabic else 'rtl')+'" hreflang="'+('en' if arabic else 'ar')+'" aria-label="'+('Switch to English' if arabic else 'التبديل إلى العربية')+'">'+('English' if arabic else 'العربية')+'</a>'

routes=['','support','aboutfilgyb','privacy','terms','privacypolicy']
for slug in routes:
 source=r/(slug+'/' if slug else '')/'index.html'
 en=source.read_text()
 # Idempotent language controls for rebuilds.
 en=re.sub(r'<a class="language-switch".*?</a>','',en)
 en=re.sub(r'<link rel="alternate" hreflang="(?:en|ar)"[^>]*>','',en)
 base='../' if slug else ''
 target=base+'ar/'+(slug+'/' if slug else '')
 en=en.replace('<nav aria-label="Main navigation">','<nav aria-label="Main navigation">'+switcher(target,False),1)
 en=en.replace('</head>',f'<link rel="alternate" hreflang="ar" href="{target}"></head>')
 source.write_text(en)
 ar=en.replace('<html lang="en">','<html lang="ar" dir="rtl">')
 ar=re.sub(r'<a class="language-switch".*?</a>',switcher(('../../'+slug+'/') if slug else '../',True),ar)
 ar=re.sub(r'<link rel="alternate" hreflang="ar"[^>]*>',f'<link rel="alternate" hreflang="en" href="'+(('../../'+slug+'/') if slug else '../')+'">',ar)
 # Assets are shared at website root; internal page links stay under /ar/.
 ar=ar.replace('../assets/','../../assets/') if slug else ar.replace('"assets/','"../assets/')
 ar=ar.replace('href="ar/','href="./').replace('href="../ar/','href="../')
 ar=re.sub(r'>([^<>]+)<',lambda m:'>'+tr(m[1])+'<',ar)
 def attr(m):return m[1]+'="'+html.escape(tr(html.unescape(m[2])),quote=True)+'"'
 ar=re.sub(r'(alt|aria-label|placeholder|content)="([^"]*)"',attr,ar)
 if slug in ('privacy','terms'):
  titles=privacyTitles if slug=='privacy' else termsTitles
  paras=privacyParas if slug=='privacy' else termsParas
  article=''.join(f'<section id="section-{i}"><h2>{i}. {title}</h2><p>{para}</p></section>' for i,(title,para) in enumerate(zip(titles,paras),1))
  ar=re.sub(r'<article>.*?</article>','<article>'+article+'</article>',ar,flags=re.S)
 ar=ar.replace('<svg viewBox=', '<svg direction="ltr" viewBox=')
 # Explicit LTR direction preserves number order within illustrative screens.
 ar=ar.replace('class="wealth-visual"','class="wealth-visual"').replace('class="card-money"','class="card-money" dir="ltr"')
 ar=ar.replace('id="contact-email"','id="contact-email" dir="ltr"')
 if slug=='privacypolicy':ar=ar.replace('url=../privacy/','url=../privacy/')
 out=r/'ar'/slug/'index.html' if slug else r/'ar/index.html'
 ar=re.sub(r'<link rel="canonical"[^>]*>', '<link rel="canonical" href="https://www.beeworksapps.com/filgybapp/ar/'+(slug+'/' if slug else '')+'">', ar)
 ar=re.sub(r'<meta property="og:url"[^>]*>', '<meta property="og:url" content="https://www.beeworksapps.com/filgybapp/ar/'+(slug+'/' if slug else '')+'">', ar)
 out.parent.mkdir(parents=True,exist_ok=True);out.write_text(ar)
(r/'tools/arabic-copy.json').write_text(json.dumps(T,ensure_ascii=False,indent=2)+'\n')
